-- ============================================================
-- ServiceTrack — Seed Database Merk (product_catalog) + backfill brand tiket
-- Sumber: databarang_20260715_1.xlsx (1064 baris, 1057 nama barang unik)
-- Jalankan SETELAH supabase-product-catalog-setup.sql
-- ============================================================

-- 1) Pastikan semua merk di file ini sudah ada di Master Brand
on conflict (name) do nothing;

-- 2) Isi Database Merk (product_catalog): nama barang -> merk
on conflict (lower(nama_barang)) do nothing;

-- 3) Backfill brand_id tiket existing yang belum ada brand-nya, matching by
--    kode_barang tiket = nama_barang di Database Merk (case-insensitive)
update public.service_tickets t
set brand_id = pc.brand_id
from public.product_catalog pc
where lower(trim(t.kode_barang)) = lower(trim(pc.nama_barang))
  and pc.brand_id is not null
  and t.brand_id is null;
